using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.USR.Parientes;using GraphApi.Services.USR.Parientes;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.USR.Parientes{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Parientes: creación, actualización y eliminación.")]    public class ParientesMutation    {        [Authorize]        [GraphQLName("createParientes")]        [GraphQLDescription("Crea un nuevo Pariente usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadParientes> CreateParientesAsync(            [GraphQLDescription("Datos necesarios para crear el Pariente.")]            clCreateParientes objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Pariente.")]            IParientesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateParientes(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateParientes")]        [GraphQLDescription("Actualiza los campos especificados de un Pariente existente.")]        public async Task<clReadParientes?> UpdateParientesAsync(            [GraphQLDescription("Datos del Pariente a actualizar.")]            clUpdateParientes objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Pariente.")]            IParientesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateParientes(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteParientes")]        [GraphQLDescription("Elimina un Pariente por su ID.")]        public async Task<bool> delParientesAsync(            [GraphQLDescription("ID del Pariente a eliminar.")]            int nParientesID,            [Service]            [GraphQLDescription("Servicio para operaciones de Pariente.")]            IParientesService objService        )        {            return await objService.DeleteParientes(nParientesID);        }    }}